figure.sourcecode:
complete-trace = { trace_id: tstr, thought_id: tstr, ? task_id: tstr / null, agent_id_hash: tstr, ; 16 lowercase hex characters started_at: tstr, ; RFC 3339 date-time completed_at: tstr, ; RFC 3339 date-time trace_level: trace-level, trace_schema_version: tstr, ; "3.0.0" as emitted today deployment_profile: deployment-profile, components: [+ trace-component], signature: tstr, ; base64 of a 64-byte Ed25519 sig signature_key_id: tstr, ; Emitted, not yet specified (see Open Issues): ? pqc_key_id: tstr, ? pubkey_ml_dsa_65: tstr, ? signature_ml_dsa_65: tstr, }
trace-level = "generic" / "detailed" / "full_traces"
deployment-profile = { agent_role: tstr, agent_template: tstr, deployment_domain: deployment-domain, deployment_type: tstr, deployment_region: tstr / null, deployment_trust_mode: "sovereign" / "limited_trust" / "federated_peer", }
deployment-domain = "healthcare" / "legal" / "financial" / "employment" / "education" / "critical_infra" / "biometric" / "law_enforcement" / "personal_assistant" / "moderation" / "research_scientific" / "manufacturing_industrial" / "general"
trace-component = { agent_id_hash: tstr, component_type: tstr, event_type: tstr, timestamp: tstr, data: { * tstr => any }, }

figure.artwork:
{
  "trace_id":             trace.trace_id,
  "thought_id":           trace.thought_id,
  "task_id":              trace.task_id,
  "agent_id_hash":        trace.agent_id_hash,
  "started_at":           trace.started_at,
  "completed_at":         trace.completed_at,
  "trace_level":          trace.trace_level,
  "trace_schema_version": trace.trace_schema_version,
  "deployment_profile": {
    "agent_role", "agent_template", "deployment_domain",
    "deployment_type", "deployment_region",
    "deployment_trust_mode"     (each from the trace)
  },
  "components": [
    for each c in trace.components, in array order:
    { "agent_id_hash":  c.agent_id_hash,
      "component_type": c.component_type,
      "data":           strip_empty(c.data),
      "event_type":     c.event_type,
      "timestamp":      c.timestamp }
  ]
}

figure.sourcecode:
trace-row-payload = { dimension: "trace:complete:v1", trace_id: tstr, ; non-empty agent_id_hash: tstr, ; non-empty run_kind: run-kind, ; CC 3.1.5; not yet emitted ( trace: { * tstr => any } ; a CompleteTrace // manifest: trace-manifest ) * tstr => any, ; members every CEG row carries }
run-kind = "production" / "prod-personal" / "prod-managed" / "qa" / "battery" / "mock"
trace-manifest = { schema: "trace_manifest:v1", content_hash: tstr, ; "sha256:" then lowercase hex byte_len: uint, ; positive component_count: uint, }
